 * A small hand-written scanner. It walks a UTF-8 source string one code
 * point at a time, tracking 1-based line/column positions, and produces a
 * flat array of tokens or throws a LexError at the first problem it finds.
 */

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const PUNCT2 = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT1 = ['+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.']

export class LexError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
    this.reason = reason
  }
}

function isLetter(c) {
  return c !== undefined && /\p{L}/u.test(c)
}

function isDigit(c) {
  return c !== undefined && c >= '0' && c <= '9'
}

function isHexDigit(c) {
  return c !== undefined && ((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F'))
}

function isBinDigit(c) {
  return c === '0' || c === '1'
}

function isOctDigit(c) {
  return c !== undefined && c >= '0' && c <= '7'
}

function isIdentStart(c) {
  return isLetter(c) || c === '_'
}

function isIdentPart(c) {
  return isLetter(c) || isDigit(c) || c === '_'
}

class Scanner {
  constructor(input) {
    this.chars = Array.from(input)
    this.idx = 0
    this.line = 1
    this.col = 1
  }

  eof() {
    return this.idx >= this.chars.length
  }

  peek(offset = 0) {
    return this.chars[this.idx + offset]
  }

  pos() {
    return { line: this.line, col: this.col }
  }

  advance() {
    const c = this.chars[this.idx]
    this.idx++
    if (c === '\n') {
      this.line++
      this.col = 1
    } else if (c === '\t') {
      this.col = (Math.floor((this.col - 1) / 4) + 1) * 4 + 1
    } else {
      this.col++
    }
    return c
  }

  error(pos, reason) {
    throw new LexError(pos.line, pos.col, reason)
  }
}

