  let out = ''
  while (true) {
    if (isDigitChar(sc.peek())) {
      out += sc.advance()
      continue
    }
    if (sc.peek() === '_' && out.length > 0 && isDigitChar(out[out.length - 1]) && isDigitChar(sc.peek(1))) {
      out += sc.advance()
      continue
    }
    break
  }
  return out
