  const start = sc.pos()
  let buffer = ''
  let bad = false

  const c0 = sc.peek()
  const c1 = sc.peek(1)
  if (c0 === '0' && (c1 === 'x' || c1 === 'X')) {
    buffer += sc.advance()
    buffer += sc.advance()
    const digits = readDigitRun(sc, isHexDigit)
    buffer += digits
    if (digits.length === 0) bad = true
  } else if (c0 === '0' && (c1 === 'b' || c1 === 'B')) {
