  let value = ''
  while (true) {
    if (sc.eof()) sc.error(start, 'unterminated string')
    const c = sc.peek()
    if (c === '"') {
      sc.advance()
      break
    }
    if (c === '\n') sc.error(sc.pos(), 'newline in string')
    if (c === '\\') {
      const backslashPos = sc.pos()
      sc.advance()
      value += scanEscape(sc, start, backslashPos)
      continue
    }
    value += sc.advance()
  }
  return { kind: 'string', line: start.line, col: start.col, text: value }
