  const start = sc.pos()
  sc.advance() // 'r'
  sc.advance() // opening quote
  let value = ''
  while (true) {
    if (sc.eof()) sc.error(start, 'unterminated string')
    const c = sc.advance()
    if (c === '"') break
    value += c
  }
  return { kind: 'rawstring', line: start.line, col: start.col, text: value }
}

