  const start = sc.pos()
  let buffer = sc.advance()
  while (isIdentPart(sc.peek())) {
    buffer += sc.advance()
  }
  const kind = KEYWORDS.has(buffer) ? 'keyword' : 'ident'
  return { kind, line: start.line, col: start.col, text: buffer }
}

function scanBlockComment(sc) {
  const start = sc.pos()
  sc.advance() // '/'
  sc.advance() // '*'
  let depth = 1
  while (depth > 0) {
    if (sc.eof()) sc.error(start, 'unterminated block comment')
    if (sc.peek() === '/' && sc.peek(1) === '*') {
