    return { kind: 'punct', line: start.line, col: start.col, text: two }
  }
  if (PUNCT1.includes(c0)) {
    sc.advance()
    return { kind: 'punct', line: start.line, col: start.col, text: c0 }
  }
  sc.error(start, `unexpected character ${c0}`)
}

