  const sc = new Scanner(input)
  const tokens = []
  while (!sc.eof()) {
    const c = sc.peek()
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      sc.advance()
      continue
    }
    if (c === '/' && sc.peek(1) === '/') {
      sc.advance()
      sc.advance()
      while (!sc.eof() && sc.peek() !== '\n') sc.advance()
      continue
    }
